package com.aiuml.architect.auth;
import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.nio.charset.StandardCharsets; import java.security.*; import java.time.*; import java.util.*;
@Service @Transactional public class AuthService { private final UserRepository users; private final RefreshTokenRepository tokens; private final PasswordEncoder passwords; AuthService(UserRepository u,RefreshTokenRepository t,PasswordEncoder p){users=u;tokens=t;passwords=p;} LoginResponse login(LoginRequest input){var user=users.findByEmailIgnoreCase(input.email()).filter(u->passwords.matches(input.password(),u.passwordHash)).orElseThrow(()->new InvalidCredentialsException()); String raw=UUID.randomUUID()+"."+UUID.randomUUID(); tokens.save(new RefreshTokenEntity(user.id,hash(raw),Instant.now().plus(Duration.ofHours(8)))); return new LoginResponse(raw,user.id,user.displayName,user.email);} public UUID userFor(String raw){return tokens.findByTokenHashAndRevokedAtIsNull(hash(raw)).filter(t->t.expiresAt.isAfter(Instant.now())).map(t->t.userId).orElseThrow(()->new InvalidCredentialsException());} static String hash(String raw){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(raw.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}} record LoginRequest(String email,String password){} record LoginResponse(String accessToken,UUID userId,String displayName,String email){} public static class InvalidCredentialsException extends RuntimeException{} }
